def mergeBruteForce(intervals: list[list[int]]) -> list[list[int]]:
    merged = True
    while merged:
        merged = False
        n = len(intervals)
        for i in range(n):
            for j in range(i + 1, n):
                if max(intervals[i][0], intervals[j][0]) <= min(intervals[i][1], intervals[j][1]):
                    new_inv = [min(intervals[i][0], intervals[j][0]), max(intervals[i][1], intervals[j][1])]
