def isRobotBoundedBruteForce(instructions: str) -> bool:
    dirX, dirY = 0, 1
    x, y = 0, 0
    for _ in range(4):
        for d in instructions:
            if d == 'G':
                x, y = x + dirX, y + dirY
            elif d == 'L':
                dirX, dirY = -dirY, dirX
            elif d == 'R':
                dirX, dirY = dirY, -dirX
        if x == 0 and y == 0:
            return True
    return x == 0 and y == 0

